-- Rollback: db/rollback/U14__drop_questions_table.sql

-- US-35/36: the shared question bank. is_system=true rows (user_id NULL)
-- are seeded, read-only, and visible to everyone; is_system=false rows are
-- a user's own additions or forks (US-36) and behave like every other
-- user-owned table for write access, even though reads of system rows are
-- shared. source_question_id records fork lineage (self-referencing,
-- nullable, same shape as resumes.parent_resume_id).
CREATE TABLE questions (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic_id             UUID NOT NULL REFERENCES topics (id),
    user_id              UUID REFERENCES users (id) ON DELETE CASCADE,
    question_text        TEXT NOT NULL,
    category             TEXT NOT NULL
                             CHECK (category IN ('dsa', 'technical', 'behavioural', 'hr',
                                                  'system_design', 'company_specific')),
    difficulty           TEXT CHECK (difficulty IN ('easy', 'medium', 'hard')),
    is_system            BOOLEAN NOT NULL DEFAULT false,
    source_question_id   UUID REFERENCES questions (id),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- US-38: every question links to exactly one topic (topic_id NOT NULL
    -- above); this check is the ownership half of that same acceptance
    -- criterion — a row is either system-owned (no user) or user-owned
    -- (no ambiguity, no orphaned personal question with a null owner).
    CONSTRAINT chk_questions_ownership
        CHECK ((is_system AND user_id IS NULL) OR (NOT is_system AND user_id IS NOT NULL))
);

CREATE INDEX idx_questions_topic_id ON questions (topic_id);
CREATE INDEX idx_questions_user_id ON questions (user_id);
CREATE INDEX idx_questions_is_system ON questions (is_system);

-- interview_questions (V10) deferred these two FKs until this migration
-- created their target tables (V10's own comment names this migration).
ALTER TABLE interview_questions
    ADD CONSTRAINT fk_interview_questions_topic FOREIGN KEY (topic_id) REFERENCES topics (id);
ALTER TABLE interview_questions
    ADD CONSTRAINT fk_interview_questions_linked_question FOREIGN KEY (linked_question_id) REFERENCES questions (id);

-- >=150 seeded system questions (US-35 acceptance criterion), 5 per topic
